const results = [];

for (const item of $input.all()) {
  const binaryData = item.binary;

  // STRICT CHECK: Dekho ki binary object exist karta hai YA NAHI, aur kya wo khali hai
  if (!binaryData || Object.keys(binaryData).length === 0) {
    // Agar image nahi hai ya khali object aaya hai, toh sirf JSON pass karo
    results.push({ json: item.json });
    continue;
  }

  const keys = Object.keys(binaryData);

  keys.forEach((key, index) => {
    results.push({
      json: {
        ...item.json,
        layer_number: index + 1,
        current_image_key: key
      },
      binary: {
        data: binaryData[key]
      }
    });
  });
}

return results;

// Gemini ka output text nikal rahe hain
const rawText = $json.content.parts[0].text;

// Markdown (```json aur ```) ko hata rahe hain
const cleanText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

// String ko wapas JSON object bana rahe hain
try {
  const jsonOutput = JSON.parse(cleanText);
  return {
    json: jsonOutput
  };
} catch (e) {
  // Agar koi image scan fail hui toh fallback
  return {
    json: {
      layer: "Error",
      chemical_name: "Unreadable",
      dosage: "Check label manually"
    }
  };
}

