const item = $input.first();

// data.json parse karo
const binaryDataBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const jsonString = binaryDataBuffer.toString('utf-8');
const parsedData = JSON.parse(jsonString);

// Saari binary fields collect karo (data.json chhod ke)
const allBinaries = {};
for (const key of Object.keys(item.binary || {})) {
  if (key !== 'data') {
    allBinaries[key] = item.binary[key];
  }
}

return [{
  json: {
    ...parsedData
  },
  binary: allBinaries
}];
